public static TFMRegistrationCollectorText defaultReferenceIdentity(int _id = 1)
{
    TFMRegistrationCollectorText refId = new TFMRegistrationCollectorText(_id, tableStr(ReferenceIdentity), "@SYS15217", "@SYS15217", "@SYS15217");
    refId.parmLocked(true);
