/// <summary>
/// Adds all menu items, that the current user has access to, to the mobile decice.
/// </summary>    
/// <returns>The menu configuration as an XML formatted string.</returns>
public XML MenuConfiguration()
{
    XmlElement          add;
    XmlElement          useStatusUpdate;
    XmlElement          menuConfiguration;
    XmlElement          items;
    UserGroupList       userGroupList;
    TFMMenuPermissions  permission;
    XmlDocument         doc;
    container           tmp;
    int                 i = 1;
    MapEnumerator		mEnum;


    doc                 = new XmlDocument();
    menuConfiguration   = doc.createElement('menuConfiguration');
    useStatusUpdate     = doc.createElement('useStatusUpdate');
    useStatusUpdate.text(TFMConstants::true());
    menuConfiguration.appendChild(useStatusUpdate);
    items               = doc.createElement('items');
    menuConfiguration.appendChild(items);

    select count(RecId) from permission;

    TFMMenuPermissions::MigrateIfNeeded();
    //this section will find all the menu items the current user may access in MenuSorting order filter for dublicates.
    while select permission
        order by MenuLineNumber, MenuSorting
        join userGroupList
            where userGroupList.userId   == curUserId()
               && permission.UserGroupId == UserGroupList.groupId
    {
        if (conFind(tmp, permission.Menu + permission.MenuGroup) == 0)              //if the menu item haven't been added
        {
            add = doc.createElement( TFMConstants::add() );
            add.setAttribute(TFMConstants::AttributeName(), permission.Menu + (permission.MenuGroup == 'MainMenu' ? '' : permission.MenuGroup) + (TFMMenuGroups::Exist(permission.Menu) ? 'Folder' : ''));
            add.setAttribute('enabled',TFMConstants::True());
            items.appendChild(add);

            tmp = conIns(tmp, i, permission.Menu + permission.MenuGroup);          //add menu item to list
            i++;
        }
    }

    return menuConfiguration.xml();
}

public boolean canBeEnqueued()
{
    return false;
}

/// <summary>
/// A method to create a simple configuration.
/// </summary>
/// <param name = "_referenceDataElement">The XML element to append the new configuration under.</param>
/// <param name = "_key">Configuration key.</param>
/// <param name = "_value">Configuration value.</param>
protected void createSimpleConfiguration(XmlElement _referenceDataElement, str _key, str _value)
{
    // This is a helper function that formats all the header configurations
    // It adds the following XML to the reference data
    // <Configuration>
    //   <Key>key</Key>
    //   <Value>
    //      Enter value here
    //   </Value>
    // </Configuration>
    //
    XmlElement      valueElement;
    XmlElement      keyElement;
    XmlElement      configurationElement;

    // Create the <Configuration> element
    configurationElement = resultXml.createElement(TFMConstants::Configuration());

    // Create the key column / element in the configuration table
    keyElement = resultXml.createElement(TFMConstants::Key());
    keyElement.text(_key);
    configurationElement.appendChild(keyElement);

    // Create the value column / element in the configuration table
    valueElement = resultXml.createElement(TFMConstants::Value());

    // Set the value
    valueElement.text(_value);

    // Add the <Value> element to the <Configuration> element
    configurationElement.appendChild(valueElement);

    // Add the <Configuration> element to the reference data
    _referenceDataElement.appendChild(configurationElement);
}

public TFMDocumentHandlerDescription description()
{
    return subStr(classStr(TFMGetReferenceData),4,100);
}

public Set getDocumentTypes()
{
    Set retMap = new Set(Types::String);
    retMap.add(subStr(classStr(TFMGetReferenceData),4,100));
    return retMap;
}

public XML getResult()
{
    XML ret;
    XmlElement  ordersElement;

    //ret = super();
    ordersElement = resultXml.firstChild();

    ret  = ordersElement.xml();

    return ret;
}

public void process()
{
    XmlElement              referenceDataElement;
    TFMRequestCapabilities  capabilities;

    resultXml   = new XmlDocument();
    referenceDataElement = resultXml.createElement(TFMConstants::ReferenceData());
    referenceDataElement.setAttribute(TFMConstants::OrderElementAttributeName(),'');
    resultXml.appendChild(referenceDataElement);
    request.makeLogEntry('Adding User Language');
    // Determine the language of the user
    this.createSimpleConfiguration(referenceDataElement, TFMConstants::UserLanguage(), TFMDocLocalization::getUserLanguage());

    request.makeLogEntry('Adding data from Document handler classes');
    // Add configuration data
    this.getConfigurationsFromDocuments(referenceDataElement);        
    this.getConfigurationsFromQueries(referenceDataElement);

    //Update device capabilities
    capabilities = request.getSubNodes(TFMConstants::capabilities());
    if(capabilities)
    {
        capabilities.updateDeviceCapabilities();
    }
}
